import {catalog,checkedDate,filterMatches,retailers} from './catalog.js';
const $=s=>document.querySelector(s);
$('#photo-retailer').insertAdjacentHTML('beforeend',retailers.map(r=>`<option value="${r}">${r}</option>`).join(''));
$('#inspo-file').multiple=true;$('#drop-zone').querySelector('strong').textContent='Add up to 5 inspiration photos';$('#drop-zone').querySelector('small').textContent='JPG, PNG or WebP · 10 MB each';$('#photo-preview').insertAdjacentHTML('beforeend','<div class="inspo-thumbs" id="inspo-thumbs"></div>');
const emptyMarkup=$('#photo-results').innerHTML;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
let photos=[],preferences={},photo=null,previewUrl=null,worker=null,timer=null,busy=false,scores=null,readVersion=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function switchMode(mode){for(const m of ['photo','planner']){$(`#${m}-mode`).hidden=m!==mode;$(`#${m}-tab`).setAttribute('aria-pressed',String(m===mode));}}
$('#photo-tab').onclick=()=>switchMode('photo');$('#planner-tab').onclick=()=>switchMode('planner');
function stop(message){clearTimeout(timer);worker?.terminate();worker=null;setBusy(false);$('#match-status').textContent=message;}
function setBusy(value){busy=value;$('#match-button').disabled=value||!photo;$('#match-button').textContent=value?'Finding your pieces…':'Find similar pieces ↗';$('#cancel-match').hidden=!value;$('#match-progress').hidden=!value;$('#photo-budget').disabled=value;$('#photo-category').disabled=value;$('#photo-retailer').disabled=value;$('#inspo-file').disabled=value;$('#remove-photo').disabled=value;if(value)$('#match-progress').removeAttribute('value');}
function clearResults(){scores=null;$('#photo-results').innerHTML=emptyMarkup;}
function clearPhoto(){readVersion++;stop('Your photo stays on your device. First use downloads the image-matching model and may take a minute.');photo=null;photos=[];$('#inspo-thumbs').innerHTML='';$('#inspo-file').value='';$('#photo-preview').hidden=true;$('#uploaded-preview').removeAttribute('src');$('#match-button').disabled=true;if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=null;$('#photo-error').textContent='';clearResults();}
async function loadPhotos(files){if(busy)return;clearPhoto();const chosen=Array.from(files||[]);if(chosen.length>5){$('#photo-error').textContent='Choose up to five photos.';return;}const version=readVersion;const loaded=[];try{for(const file of chosen){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Use JPG, PNG or WebP images under 10 MB each.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(version!==readVersion)return;if(!img.naturalWidth||img.naturalWidth*img.naturalHeight>80000000)throw Error('Choose a smaller image.');const scale=Math.min(1,1024/Math.max(img.naturalWidth,img.naturalHeight));const c=document.createElement('canvas');c.width=Math.round(img.naturalWidth*scale);c.height=Math.round(img.naturalHeight*scale);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);loaded.push(c.toDataURL('image/jpeg',.9));}finally{URL.revokeObjectURL(url);}}if(version!==readVersion)return;photos=loaded;photo=photos[0];if(!photo)return;$('#uploaded-preview').src=photo;$('#photo-preview').hidden=false;$('#inspo-thumbs').innerHTML=photos.map((src,i)=>`<img src="${src}" alt="Inspiration ${i+1}">`).join('');$('#match-button').disabled=false;$('#match-status').textContent=photos.length+' photos ready. Their match scores will be combined.';}catch(error){$('#photo-error').textContent=error.message||'Could not read those photos.';}}
$('#inspo-file').addEventListener('change',e=>loadPhotos(e.target.files));$('#remove-photo').onclick=clearPhoto;
for(const event of ['dragenter','dragover'])$('#drop-zone').addEventListener(event,e=>{e.preventDefault();if(!busy)$('#drop-zone').classList.add('dragging');});
for(const event of ['dragleave','drop'])$('#drop-zone').addEventListener(event,e=>{e.preventDefault();$('#drop-zone').classList.remove('dragging');if(event==='drop'&&!busy)loadPhotos(e.dataTransfer.files);});
$('#cancel-match').onclick=()=>{stop('Matching cancelled. Your photo is ready when you are.');clearResults();};
$('#photo-results').addEventListener('error',e=>{if(e.target.matches('.product-image')){e.target.hidden=true;e.target.nextElementSibling.hidden=false;}},true);
function showResults(){if(!scores)return;const budget=Number($('#photo-budget').value),category=$('#photo-category').value;const found=filterMatches(scores.map(s=>({...s,score:s.score*(preferences[s.label]===1?1.5:preferences[s.label]===-1?.2:1)})),{budget,category,retailer:$('#photo-retailer').value});if(!found.length){$('#photo-results').innerHTML='<div class="photo-empty"><p class="eyebrow">NO CLOSE MATCHES IN THIS CATALOG</p><h2>Let’s try a different angle.</h2><p>No close catalog matches fit these filters. Try another retailer or furniture category, a higher per-piece budget, or a photo focused on one item.</p><p class="note">We won’t fill the results with unrelated products.</p></div>';return;}
 $('#photo-results').innerHTML=`<div class="match-head"><div><p class="eyebrow">YOUR PHOTO → REAL PIECES</p><h2>Similar pieces to shop</h2></div><span class="badge">${found.length} suggestions</span></div><p class="results-note">Ranked by visual similarity to product descriptions in our ${catalog.length}-piece catalog across ${retailers.length} US retailers. These are alternatives, not a room bundle or guaranteed exact matches.</p><div class="match-grid">${found.map(({product:p},i)=>`<article class="product"><a class="product-photo-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer" aria-label="View ${esc(p.name)} ${esc(p.type)} at ${esc(p.retailer)}"><img class="product-image" src="${esc(p.image)}" alt="${esc(p.name)} ${esc(p.type)} — ${esc(p.detail)}" width="640" height="480" loading="lazy" decoding="async"><span class="image-unavailable" hidden>Photo unavailable · View at ${esc(p.retailer)} ↗</span></a><div class="product-body"><div class="card-top"><span>${esc(p.retailer)} · ${esc(p.type)}</span><span>#${i+1}</span></div><div class="product-swatches" aria-label="Approximate product colors">${p.swatches.map(c=>`<span style="background:${c}"></span>`).join('')}</div><h3>${esc(p.name)}</h3><p>${esc(p.detail)}</p><p class="note">Checked ${esc(p.checkedDate)}</p>${p.note?`<p class="note">${esc(p.note)}</p>`:''}<div class="product-bottom"><div><span class="product-price">${money(p.price)}</span><div class="note">Listed price · USD</div></div><a class="shop-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">View at ${esc(p.retailer)} ↗</a></div><div class="feedback-actions"><button data-save="${esc(p.id)}">Save to room board</button><button data-feedback="${esc(p.id)}" data-value="1" aria-pressed="${preferences[p.caption]===1}">More like this</button><button data-feedback="${esc(p.id)}" data-value="-1" aria-pressed="${preferences[p.caption]===-1}">Less like this</button></div></div></article>`).join('')}</div><p class="results-note">Product listings checked ${checkedDate}. Prices are not live; tax and delivery are extra. Confirm current price, dimensions and availability on the retailer’s page. Color swatches are approximate.</p>`;
}
for(const id of ['photo-budget','photo-category','photo-retailer'])$('#'+id).addEventListener('change',()=>{if($('#photo-form').checkValidity())showResults();});
$('#photo-form').addEventListener('submit',e=>{e.preventDefault();if(!photo||busy)return;$('#photo-error').textContent='';if(scores){showResults();return;}setBusy(true);$('#photo-results').innerHTML='<div class="photo-empty"><p class="eyebrow">FINDING YOUR NEXT PIECE</p><h2>Taking a closer look.</h2><p>Comparing the shapes, materials and colors in your inspiration to real furniture listings.</p></div>';
 try{if(!worker)worker=new Worker(new URL('./matcher-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.type==='status'||data.type==='progress'){$('#match-status').textContent=data.text;if(data.type==='progress')$('#match-progress').value=data.value;else $('#match-progress').removeAttribute('value');return;}clearTimeout(timer);setBusy(false);if(data.type==='result'){scores=data.scores;showResults();$('#match-status').textContent='Done. Adjust price or category to refine your matches.';if(innerWidth<641)$('#photo-results').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}else if(data.type==='unrecognized'){$('#match-status').textContent='Try a furniture photo.';$('#photo-results').innerHTML='<div class="photo-empty"><h2>Try a clearer furniture photo.</h2><p>We couldn’t confidently recognize furniture in this image. Try a room photo or a close-up of a furniture piece.</p></div>';}else{stop('Photo matching is unavailable right now.');$('#photo-error').textContent=data.message;clearResults();}};worker.onerror=()=>{stop('Photo matching is unavailable right now.');$('#photo-error').textContent='The image matcher could not start. Check your connection and try again. The style planner still works.';clearResults();};timer=setTimeout(()=>{stop('Matching took too long.');$('#photo-error').textContent='The model download or analysis timed out. Try again on a faster connection; downloaded files may already be cached.';clearResults();},180000);worker.postMessage({images:photos,labels:catalog.map(p=>p.caption)});}catch{stop('Photo matching is unavailable in this browser.');$('#photo-error').textContent='Try an up-to-date browser with WebAssembly support.';clearResults();}
});
window.addEventListener('pagehide',()=>{worker?.terminate();if(previewUrl)URL.revokeObjectURL(previewUrl);});

$('#photo-results').addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.save){window.dispatchEvent(new CustomEvent('roomedit-save',{detail:button.dataset.save}));button.textContent='Saved to board';button.disabled=true;}if(button.dataset.feedback){const p=catalog.find(p=>p.id===button.dataset.feedback);preferences[p.caption]=Number(button.dataset.value);showResults();$('#match-status').textContent='Ranking adjusted for this session. Your feedback changes this product’s priority.';}});
